            for (int j = 1; j <= i; ++j)
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
        }
    }

    static long compute_diff(int conf, int a_prev, int b_prev) {
        long total_diff = 0;
        for (int i = 0; i <= c; ++i) {
            if ((conf & (1 << i)) != 0) {
                b_prev++;
                long aux1 = comb[b_prev - 1][r - 1];
                long aux2 = comb[n - b_prev][r] - comb[a_prev][r];
                total_diff -= aux1 * aux2;
            } else {
                a_prev++;
                long aux1 = comb[a_prev - 1][r - 1];
                long aux2 = comb[n - a_prev][r] - comb[b_prev][r];
                total_diff += aux1 * aux2;
            }
        }
        return total_diff;
    }

    static boolean is_valid_conf(int conf) {
        for (int i = 0; i <= c; ++i) {
