                long count_coef = count_in_vector(partials[c + 1 - a_count], partialsZero[c + 1 - a_count].get(indexZero));
                if (Math.abs(val) <= answer[0]) {
                    update_result(answer, new long[]{Math.abs(val), zero_coef * count_coef});
